41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	
49	const BASE_PREMIUMS: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
59	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	
64	const countsByType = (items: Item[]): Map<string, number> =>
65	  items.reduce(
66	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
67	    new Map<string, number>(),
68	  );
69	
70	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
71	
72	/** Exactly three alike components form a building block, priced at a flat rate. */
73	const basePremiumForAlikeItems = (type: string, count: number): number =>
74	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
75	    ? COMPONENT_BLOCK_PREMIUM
76	    : count * BASE_PREMIUMS[type];
77	
78	const policyBasePremium = (items: Item[]): number =>
79	  [...countsByType(items)].reduce(
80	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
81	    0,
82	  );
83	
84	/**
85	 * Modifiers are rates on a base premium, never on each other, so each one is
86	 * measured against the same base and the results are summed.
87	 */
88	const amountOf = (rate: number, basePremium: number): number => rate * basePremium;
89	
90	/** Item-specific surcharge rates stack additively on the item's own base premium. */
91	const surchargeRateFor = (item: Item): number =>
92	  (item.cursed ? CURSE_SURCHARGE : 0) +
93	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
94	
95	/** Item-specific surcharges are rates on the affected item's own base premium. */
96	const itemSurcharges = (items: Item[]): number =>
97	  items.reduce(
98	    (total, item) => total + amountOf(surchargeRateFor(item), BASE_PREMIUMS[item.type]),
99	    0,
100	  );
101	
102	/** Policy-wide rates apply to the policy base premium; discounts are negative. */
103	const policyRateFor = (customer: Customer): number =>
104	  INITIAL_ASSESSMENT_SURCHARGE +
105	  (customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0);
106	
107	const quote = (step: QuoteStep, customer: Customer): StepResult => {
108	  const base = policyBasePremium(step.items);
109	  const modifiers = itemSurcharges(step.items) + amountOf(policyRateFor(customer), base);
110	  return {
111	    premium: roundPremiumInMHPCOFavour(base + modifiers + PROCESSING_FEE),
112	  };
113	};
114	
115	const runStep = (step: Step, customer: Customer): StepResult => {
116	  if (step.op === "quote") return quote(step, customer);
117	  throw new Error(`Unsupported step: ${step.op}`);
118	};
119	
120	export const runScenario = (scenario: Scenario): ScenarioResult => ({
121	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
122	});
